// Package sqlite is the quiz module's Repo on the platform database (queries.sql, generated by sqlc).
package sqlite

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"time"

	"github.com/IhebBelhadj/opsforge-academy/academy/internal/platform/sqlite"
	"github.com/IhebBelhadj/opsforge-academy/academy/internal/quiz"
)

// Repo implements quiz.Repo.
type Repo struct {
	q *Queries
}

var _ quiz.Repo = (*Repo)(nil)

// NewRepo uses the open database db.
func NewRepo(db *sql.DB) *Repo { return &Repo{q: New(db)} }

// Create stores a new attempt and returns its id.
func (r *Repo) Create(ctx context.Context, a quiz.Attempt) (int64, error) {
	questions, err := json.Marshal(a.Questions)
	if err != nil {
		return 0, err
	}
	return r.q.InsertAttempt(ctx, InsertAttemptParams{UserID: a.UserID, CourseID: a.Course, ItemID: a.Item,
		ContentHash: a.Hash, StartedAt: sqlite.FormatTime(a.StartedAt), Deadline: optText(a.Deadline),
		Questions: string(questions), Pass: int64(a.Pass), Offered: int64(a.Offered)})
}

// Attempt reads one attempt, or quiz.ErrAttemptNotFound.
func (r *Repo) Attempt(ctx context.Context, id int64) (quiz.Attempt, error) {
	row, err := r.q.GetAttempt(ctx, id)
	if errors.Is(err, sql.ErrNoRows) {
		return quiz.Attempt{}, quiz.ErrAttemptNotFound
	}
	if err != nil {
		return quiz.Attempt{}, err
	}
	return attempt(row)
}

// Submit records a graded attempt; quiz.ErrSubmitted if it already was.
func (r *Repo) Submit(ctx context.Context, a quiz.Attempt) error {
	answers, err := json.Marshal(a.Answers)
	if err != nil {
		return err
	}
	n, err := r.q.SubmitAttempt(ctx, SubmitAttemptParams{SubmittedAt: optText(a.SubmittedAt),
		Answers: sql.NullString{String: string(answers), Valid: true}, Correct: int64(a.Correct),
		Score: int64(a.Score), Passed: boolInt(a.Passed), Xp: int64(a.XP), ID: a.ID})
	if err != nil {
		return err
	}
	if n == 0 {
		return quiz.ErrSubmitted
	}
	return nil
}

// Attempts are user's attempts at an item, newest first.
func (r *Repo) Attempts(ctx context.Context, user int64, course, item string) ([]quiz.Attempt, error) {
	rows, err := r.q.ItemAttempts(ctx, ItemAttemptsParams{UserID: user, CourseID: course, ItemID: item})
	if err != nil {
		return nil, err
	}
	return attempts(rows)
}

// Passed are user's passed attempts, oldest first.
func (r *Repo) Passed(ctx context.Context, user int64) ([]quiz.Attempt, error) {
	rows, err := r.q.PassedAttempts(ctx, user)
	if err != nil {
		return nil, err
	}
	return attempts(rows)
}

func attempts(rows []QuizAttempt) ([]quiz.Attempt, error) {
	out := make([]quiz.Attempt, len(rows))
	for i, row := range rows {
		a, err := attempt(row)
		if err != nil {
			return nil, err
		}
		out[i] = a
	}
	return out, nil
}

func attempt(row QuizAttempt) (quiz.Attempt, error) {
	a := quiz.Attempt{ID: row.ID, UserID: row.UserID, Course: row.CourseID, Item: row.ItemID, Hash: row.ContentHash,
		Pass: int(row.Pass), Offered: int(row.Offered), Correct: int(row.Correct), Score: int(row.Score),
		Passed: row.Passed == 1, XP: int(row.Xp)}
	var err error
	if a.StartedAt, err = sqlite.ParseTime(row.StartedAt); err != nil {
		return a, err
	}
	if a.Deadline, err = optTime(row.Deadline); err != nil {
		return a, err
	}
	if a.SubmittedAt, err = optTime(row.SubmittedAt); err != nil {
		return a, err
	}
	if err := json.Unmarshal([]byte(row.Questions), &a.Questions); err != nil {
		return a, err
	}
	if row.Answers.Valid {
		if err := json.Unmarshal([]byte(row.Answers.String), &a.Answers); err != nil {
			return a, err
		}
	}
	return a, nil
}

func boolInt(b bool) int64 {
	if b {
		return 1
	}
	return 0
}

func optText(t *time.Time) sql.NullString {
	if t == nil {
		return sql.NullString{}
	}
	return sql.NullString{String: sqlite.FormatTime(*t), Valid: true}
}

func optTime(s sql.NullString) (*time.Time, error) {
	if !s.Valid {
		return nil, nil
	}
	t, err := sqlite.ParseTime(s.String)
	return &t, err
}
